const NAS_BASE_PATH = '/home/node/n8n-files/projects';

const input = $input.first().json;
const projectId = input.body?.project_id || '';
const folderPath = input.body?.folder_path || '';
const fileName = input.body?.file_name || '';

if (!projectId) throw new Error('Geen project_id opgegeven.');
if (!folderPath) throw new Error('Geen folder_path opgegeven.');
if (!fileName) throw new Error('Geen file_name opgegeven.');

if (folderPath.includes('..') || folderPath.startsWith('/') || fileName.includes('..') || fileName.includes('/')) {
  throw new Error('Ongeldig pad.');
}

const filePath = `${NAS_BASE_PATH}/${projectId}/${folderPath}/${fileName}`;

return [{ json: { projectId, folderPath, fileName, filePath } }];

const result = $input.first().json;
const stdout = (result.stdout || '').trim();
const setup = $('Setup').first().json;

if (stdout === 'DELETED') {
  return [{ json: { success: true, message: `Bestand '${setup.fileName}' verwijderd.` } }];
} else if (stdout === 'NOT_FOUND') {
  return [{ json: { success: false, message: `Bestand '${setup.fileName}' bestaat niet.` } }];
} else {
  return [{ json: { success: false, message: `Fout bij verwijderen van '${setup.fileName}'.` } }];
}
